return [{ json: { search_profile_id: inp.search_profile_id, profile_version: inp.version || ctx.profile_version || 1, max_per_query: ctx.max_per_query || 5, research_min_fit: ctx.research_min_fit || 30, max_research: ctx.max_research || 3, people_min_fit: ctx.people_min_fit || 30, max_people_companies: ctx.max_people_companies || 3, spend_cap_usd: (ctx.spend_cap_usd === undefined ? null : ctx.spend_cap_usd), discovery_cache_ttl_hours: ctx.discovery_cache_ttl_hours || 24, discovery_source: ctx.discovery_source || 'places', import_sheet_id: ctx.import_sheet_id || '', import_tab: ctx.import_tab || 'Import', coverage_min_ratio: ctx.coverage_min_ratio || 0, contact_min_fit: ctx.contact_min_fit || 30, max_contact_companies: ctx.max_contact_companies || 10, contact_provider_enabled: ctx.contact_provider_enabled === true, linkedin_people_enabled: ctx.linkedin_people_enabled === true, linkedin_min_fit: ctx.linkedin_min_fit || 30, max_linkedin_companies: ctx.max_linkedin_companies || 10, linkedin_max_employees: ctx.linkedin_max_employees || 10, xray_people_enabled: ctx.xray_people_enabled === true, xray_min_fit: ctx.xray_min_fit || ctx.linkedin_min_fit || 30, max_xray_companies: ctx.max_xray_companies || 10, publish_limit: ctx.publish_limit || 200, approval_sheet_id_vnext: ctx.approval_sheet_id_vnext || '' } }];

